head.script:
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 1. 브라우저에서 개발자도구 (F12) 를 실행한다.
    //1. Run the Developer Tool (F12) in your browser.
    //Test step 2. src 부분을 확인한다.
    //2. Check the src part.
    //Verify2. src="" 로 표시된다.  (그전버전에서는 그림1처럼 src="/xmlSample/test/" 로 표시됨)
    //2. src = '' is displayed. (As in previous versions, shown as src = '/ xmlSample / test /' in Figure 1)
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#wq_uuid_5').attr('src') == ''", "true");
    WebSquare.wUnit.addCommand("pause", "1000");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //Function unitTest
    //Create buy Truong.Luu
    //Create date 31-Jan-2018
    //End unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
